const int BOTON = 19;            // pulsador: entrada digital
const int POT = 32;              // potenciómetro: entrada analógica
const int RELAY = 14;            // relé: salida digital
const int LED = 23;              // LED: salida, se le puede dar PWM
void setup() {
  pinMode(BOTON, INPUT_PULLUP);  // suelto = HIGH, apretado = LOW
  pinMode(RELAY, OUTPUT);
  pinMode(LED, OUTPUT);
}
void loop() {
  if (digitalRead(BOTON) == LOW) digitalWrite(RELAY, HIGH);   // apretado: prende
  int valor = analogRead(POT);   // 0..4095
  analogWrite(LED, valor / 16);  // 0..255: el brillo
  // el DHT22 (pin 33) se lee con su librería: no pasa por el ADC
  // un motor DC nunca directo al pin: transistor o driver
}

