const int POT = 32, LED = 26;
void setup() { pinMode(LED, OUTPUT); }
void loop() {
  int lectura = analogRead(POT);                // 0..4095: 12 bits = 4096 valores
  float volt = lectura * 3.3 / 4095;            // de 0 a 3,3 V
  int brillo = map(lectura, 0, 4095, 0, 255);   // con 2048 da 127
  // 127 de 255: duty ≈ 50 %, tensión promedio ≈ 1,64 V
  analogWrite(LED, brillo);
  // dacWrite(25, 127) daría 1,64 V continuos de verdad
}

